import {frameAction,fieldCameraOffset} from './camera-framing.js';
import * as THREE from './vendor/three.module.js';
const clamp=THREE.MathUtils.clamp;
function sphereHit(start,delta,center,radius){const m=start.clone().sub(center),a=delta.lengthSq(),b=2*m.dot(delta),c=m.lengthSq()-radius*radius;if(c<=0)return 0;if(a<1e-12)return null;const disc=b*b-4*a*c;if(disc<0)return null;const t=(-b-Math.sqrt(disc))/(2*a);return t>=0&&t<=1?t:null;}
// Continuous sphere against a finite post/bar, including its rounded ends.
export function sweepCapsule(start,end,a,b,radius){const axis=b.clone().sub(a),length=axis.length();axis.divideScalar(length||1);const delta=end.clone().sub(start),m=start.clone().sub(a),mAxis=m.dot(axis),dAxis=delta.dot(axis),mp=m.clone().addScaledVector(axis,-mAxis),dp=delta.clone().addScaledVector(axis,-dAxis);const candidates=[];const nearest=a.clone().addScaledVector(axis,clamp(mAxis,0,length));if(start.distanceTo(nearest)<=radius)candidates.push(0);const aa=dp.lengthSq(),bb=2*mp.dot(dp),cc=mp.lengthSq()-radius*radius,disc=bb*bb-4*aa*cc;if(aa>1e-12&&disc>=0){const t=(-bb-Math.sqrt(disc))/(2*aa),along=mAxis+dAxis*t;if(t>=0&&t<=1&&along>=0&&along<=length)candidates.push(t);}for(const cap of [a,b]){const t=sphereHit(start,delta,cap,radius);if(t!==null)candidates.push(t);}if(!candidates.length)return null;const t=Math.min(...candidates),point=start.clone().lerp(end,t),closest=a.clone().addScaledVector(axis,clamp(point.clone().sub(a).dot(axis),0,length)),normal=point.clone().sub(closest).normalize();return {t,point,normal};}
export function goalFrame(x,z,nx,nz,width,height,options={}){return {center:new THREE.Vector3(x,0,z),normal:new THREE.Vector3(nx,0,nz).normalize(),width,height,...options};}
export function collideGoalFrames(mesh,velocity,before,goals,radius=.12){let contact=null;for(const goal of goals){const side=new THREE.Vector3(-goal.normal.z,0,goal.normal.x),left=goal.center.clone().addScaledVector(side,-goal.width/2),right=goal.center.clone().addScaledVector(side,goal.width/2),topLeft=left.clone().setY(goal.postHeight??goal.height),topRight=right.clone().setY(goal.postHeight??goal.height);for(const [a,b]of [[left,topLeft],[right,topRight],...(goal.crossbar===false?[]:[[topLeft,topRight]])]){const hit=sweepCapsule(before,mesh.position,a,b,radius+(goal.postRadius??.045));if(hit&&velocity.dot(hit.normal)<0&&(!contact||hit.t<contact.t))contact={...hit,goal};}}if(!contact)return null;mesh.position.copy(contact.point).addScaledVector(contact.normal,.004);velocity.addScaledVector(contact.normal,-1.72*velocity.dot(contact.normal));return contact.goal;}
export function crossedGoal(before,after,goal,radius=.12){const from=before.clone().sub(goal.center).dot(goal.normal),to=after.clone().sub(goal.center).dot(goal.normal);if(from>radius||to<=radius)return false;const t=(radius-from)/(to-from),cross=before.clone().lerp(after,t),side=new THREE.Vector3(-goal.normal.z,0,goal.normal.x);return Math.abs(cross.clone().sub(goal.center).dot(side))<goal.width/2-radius&&cross.y+radius<goal.height;}
export function shootoutWinner(shots,scores){if(shots[0]<5||shots[1]<5){if(scores[0]>scores[1]+Math.max(0,5-shots[1]))return 0;if(scores[1]>scores[0]+Math.max(0,5-shots[0]))return 1;}if(shots[0]===shots[1]&&shots[0]>=5&&scores[0]!==scores[1])return scores[0]>scores[1]?0:1;return null;}
export function footballCamera(player,ball,aspect=1.5,view='broadcast',direction=1){
 const p=player.position||player,b=ball.position||ball;
 const offset=view==='high'?[-2,24,17]:view==='behind'?[-direction*9,6.5,4]:fieldCameraOffset(aspect,direction);
 const frame=frameAction(p,b,aspect,offset);
 if((view==='behind'||(view==='broadcast'&&aspect<.85))&&Math.abs(frame.look.x)>12){frame.position.x=clamp(frame.position.x,-21,21);frame.position.y=Math.max(9,frame.position.y);}
 return frame;
}
